from collections import defaultdict
from datetime import date, timedelta


class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: list[date] | None = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = set(holidays) if holidays is not None else set()
        # Maps employee name -> dict of {year: days_used}
        self._used_leave: dict[str, dict[int, int]] = defaultdict(lambda: defaultdict(int))

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        """Request leave from start to end (inclusive); returns the number of leave days used."""
        if end < start:
            raise ValueError("Leave end date cannot be before the start date.")

        # Calculate requested leave days per calendar year
        days_per_year: dict[int, int] = defaultdict(int)
        curr = start
        while curr <= end:
            # Monday is 0, Sunday is 6; weekends are 5 and 6
            if curr.weekday() < 5 and curr not in self.holidays:
                days_per_year[curr.year] += 1
            curr += timedelta(days=1)

        # Check if the employee has enough leave days remaining for each affected year
        for yr, requested_days in days_per_year.items():
            if requested_days > self.remaining(employee, yr):
                raise ValueError(
                    f"Employee '{employee}' does not have enough remaining leave days for year {yr}."
                )

        # Record the leave days
        for yr, requested_days in days_per_year.items():
            self._used_leave[employee][yr] += requested_days

        return sum(days_per_year.values())

    def remaining(self, employee: str, year: int) -> int:
        """Returns the number of remaining leave days for an employee in a given year."""
        used = self._used_leave[employee][year]
        return self.days_per_year - used
